package com.zomiggy.controller; import com.zomiggy.dto.ApiDtos.Address; import jakarta.validation.constraints.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/locations") public class LocationController { @GetMapping("/reverse") public Address reverse(@RequestParam @DecimalMin("-90") @DecimalMax("90") double latitude,@RequestParam @DecimalMin("-180") @DecimalMax("180") double longitude){return new Address("Lat %.4f, Lng %.4f".formatted(latitude,longitude),latitude,longitude);} @GetMapping("/search") public Address search(@RequestParam @NotBlank String q){return new Address(q,17.4399,78.4983);} }